from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def replace_once(path: Path, old: str, new: str) -> None:
    text = path.read_text(encoding='utf-8')
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f'{path}: expected exactly one match, got {count}')
    path.write_text(text.replace(old, new, 1), encoding='utf-8')


transaction = ROOT / 'pages' / 'zz_cloud' / 'upload_transaction.mjs'
replace_once(
    transaction,
    """    if (!item.path || typeof item.loadContentBase64 !== 'function') {\n      throw new Error('上传图片描述不完整');\n    }\n""",
    """    if (\n      !item.path\n      || (typeof item.loadContentBase64 !== 'function' && typeof item.createBlob !== 'function')\n    ) {\n      throw new Error('上传图片描述不完整');\n    }\n""",
)
replace_once(
    transaction,
    """  const blobEntries = await boundedMap(objects, concurrency, async object => {\n    let content = await object.loadContentBase64();\n    try {\n      const result = await safeObjectRequest(\n        request,\n        'POST',\n        `${api}/git/blobs`,\n        { body: { content, encoding: 'base64' } },\n        sleep,\n      );\n      const sha = result?.data?.sha;\n      if (!sha) throw new Error(`GitHub blob 创建失败：${object.path}`);\n      completed++;\n      onProgress(completed, objects.length);\n      return { path: object.path, mode: '100644', type: 'blob', sha };\n    } finally {\n      content = null;\n    }\n  });\n""",
    """  const blobEntries = await boundedMap(objects, concurrency, async object => {\n    let sha = '';\n    if (typeof object.createBlob === 'function') {\n      sha = await object.createBlob();\n    } else {\n      let content = await object.loadContentBase64();\n      try {\n        const result = await safeObjectRequest(\n          request,\n          'POST',\n          `${api}/git/blobs`,\n          { body: { content, encoding: 'base64' } },\n          sleep,\n        );\n        sha = result?.data?.sha || '';\n      } finally {\n        content = null;\n      }\n    }\n    if (!sha) throw new Error(`GitHub blob 创建失败：${object.path}`);\n    completed++;\n    onProgress(completed, objects.length);\n    return { path: object.path, mode: '100644', type: 'blob', sha };\n  });\n""",
)

app = ROOT / 'pages' / 'zz_cloud' / 'app.js'
replace_once(
    app,
    "const WRITE_METHODS = new Set(['POST', 'PUT', 'PATCH', 'DELETE']);\n",
    "const WRITE_METHODS = new Set(['POST', 'PUT', 'PATCH', 'DELETE']);\nconst CLOUD_PROXY_BLOB_THRESHOLD_BYTES = 4 * 1024 * 1024;\n",
)
replace_once(
    app,
    """function fileToBase64(file) {\n  return new Promise((res, rej) => {\n    const r = new FileReader();\n    r.onload = () => res(r.result.split(',')[1]);\n    r.onerror = rej;\n    r.readAsDataURL(file);\n  });\n}\n\n""",
    """function fileToBase64(file) {\n  return new Promise((res, rej) => {\n    const r = new FileReader();\n    r.onload = () => res(r.result.split(',')[1]);\n    r.onerror = rej;\n    r.readAsDataURL(file);\n  });\n}\n\nfunction formatMiB(bytes) {\n  return `${(Number(bytes || 0) / (1024 * 1024)).toFixed(1)} MiB`;\n}\n\nfunction largeGitHubBlobProxyPath(cfg) {\n  return `/__gallery-github-blob/${encodeURIComponent(cfg.owner)}/${encodeURIComponent(cfg.repo)}`;\n}\n\nfunction largeBlobRetryable(error) {\n  const status = Number(error?.status || 0);\n  return error?.retryable === true\n    || !status\n    || status === 429\n    || [500, 502, 503, 504].includes(status);\n}\n\nasync function uploadLargeGitHubBlob(file, gitPath, cfg) {\n  if (!cfg.token) throw new Error('大图片上传需要有效 GitHub Token');\n  let lastError = null;\n  for (let attempt = 0; attempt < 3; attempt++) {\n    progressText.textContent = `正在上传大图片 ${file.name || gitPath}（${formatMiB(file.size)}）${\n      attempt ? `，重试 ${attempt + 1}/3` : ''\n    }...`;\n    try {\n      const resp = await fetch(largeGitHubBlobProxyPath(cfg), {\n        method: 'POST',\n        headers: {\n          Authorization: `token ${cfg.token}`,\n          'Content-Type': 'application/octet-stream',\n          'X-Gallery-Blob-Size': String(file.size),\n          'X-Gallery-Path': gitPath,\n        },\n        body: file,\n      });\n      let data = null;\n      try { data = await resp.json(); } catch { data = null; }\n      if (!resp.ok) {\n        const err = new Error(data?.message || `大图片代理上传失败：HTTP ${resp.status}`);\n        err.status = resp.status;\n        const rateLimited = resp.status === 429\n          || resp.headers.get('x-ratelimit-remaining') === '0'\n          || /rate limit/i.test(data?.message || '');\n        if (rateLimited || [500, 502, 503, 504].includes(resp.status)) err.retryable = true;\n        const retryAfterSeconds = Number(resp.headers.get('retry-after') || 0);\n        if (retryAfterSeconds > 0) {\n          err.retryAfterMs = Math.min(10_000, Math.max(250, retryAfterSeconds * 1000));\n        }\n        throw err;\n      }\n      const sha = data?.sha;\n      if (!sha) throw new Error('GitHub 大图片 Blob 创建成功但未返回 SHA');\n      return sha;\n    } catch (error) {\n      lastError = error;\n      if (!largeBlobRetryable(error) || attempt === 2) throw error;\n      const delay = error?.retryAfterMs ?? (500 * (2 ** attempt));\n      await new Promise(resolve => setTimeout(resolve, Math.min(10_000, delay)));\n    }\n  }\n  throw lastError || new Error('大图片代理上传失败');\n}\n\n""",
)
replace_once(
    app,
    """      const blobConcurrency = plannedUploads.some(\n        result => result.item.file.size > 16 * 1024 * 1024,\n      ) ? 1 : 2;\n""",
    """      const blobConcurrency = plannedUploads.some(\n        result => result.item.file.size >= CLOUD_PROXY_BLOB_THRESHOLD_BYTES,\n      ) ? 1 : 2;\n""",
)
replace_once(
    app,
    """        items: plannedUploads.map(result => ({\n          path: result.gitPath,\n          size: result.item.file.size,\n          expectedBlobSha: result.item.blobSha,\n          loadContentBase64: () => fileToBase64(result.item.file),\n        })),\n""",
    """        items: plannedUploads.map(result => {\n          const useBinaryProxy = result.item.file.size >= CLOUD_PROXY_BLOB_THRESHOLD_BYTES;\n          return {\n            path: result.gitPath,\n            size: result.item.file.size,\n            expectedBlobSha: result.item.blobSha,\n            loadContentBase64: () => fileToBase64(result.item.file),\n            createBlob: useBinaryProxy ? async () => {\n              const sha = await uploadLargeGitHubBlob(result.item.file, result.gitPath, uploadConfig);\n              if (result.item.blobSha && sha !== result.item.blobSha) {\n                throw new Error(`大图片上传完整性校验失败：${result.gitPath}`);\n              }\n              return sha;\n            } : null,\n          };\n        }),\n""",
)
replace_once(
    app,
    """        onProgress: (completed, total) => {\n          progressText.textContent = `准备远端对象 ${completed} / ${total}...`;\n          progressBar.value = (completed / total) * 90;\n        },\n""",
    """        onProgress: (completed, total) => {\n          progressText.textContent = completed === total\n            ? '远端对象准备完成，正在提交图库事务...'\n            : `远端对象已完成 ${completed} / ${total}，正在继续准备...`;\n          progressBar.value = (completed / total) * 90;\n        },\n""",
)

blob_stream = ROOT / 'pages' / 'zz_cloud' / 'blob_stream.mjs'
blob_stream.write_text("""const ENCODER = new TextEncoder();\nconst JSON_PREFIX = ENCODER.encode('{\\"content\\":\\"');\nconst JSON_SUFFIX = ENCODER.encode('\\",\\"encoding\\":\\"base64\\"}');\nconst BASE64_BLOCK_BYTES = 3 * 8192;\n\nfunction bytesToBase64(bytes) {\n  let output = '';\n  for (let offset = 0; offset < bytes.length; offset += BASE64_BLOCK_BYTES) {\n    const part = bytes.subarray(offset, Math.min(bytes.length, offset + BASE64_BLOCK_BYTES));\n    let binary = '';\n    for (let i = 0; i < part.length; i++) binary += String.fromCharCode(part[i]);\n    output += btoa(binary);\n  }\n  return output;\n}\n\nfunction mergeCarry(carry, chunk) {\n  if (!carry.length) return chunk;\n  const merged = new Uint8Array(carry.length + chunk.length);\n  merged.set(carry, 0);\n  merged.set(chunk, carry.length);\n  return merged;\n}\n\nexport function createGitHubBlobJsonStream(source, { maxBytes = 100 * 1024 * 1024 } = {}) {\n  if (!source || typeof source.getReader !== 'function') {\n    throw new Error('GitHub blob source stream is unavailable');\n  }\n  const reader = source.getReader();\n  let carry = new Uint8Array(0);\n  let total = 0;\n  let finished = false;\n\n  return new ReadableStream({\n    start(controller) {\n      controller.enqueue(JSON_PREFIX);\n    },\n    async pull(controller) {\n      if (finished) return;\n      try {\n        while (true) {\n          const { value, done } = await reader.read();\n          if (done) {\n            if (carry.length) controller.enqueue(ENCODER.encode(bytesToBase64(carry)));\n            controller.enqueue(JSON_SUFFIX);\n            controller.close();\n            finished = true;\n            return;\n          }\n          const incoming = value instanceof Uint8Array ? value : new Uint8Array(value);\n          total += incoming.byteLength;\n          if (total > maxBytes) {\n            finished = true;\n            try { await reader.cancel('raw blob exceeds limit'); } catch {}\n            controller.error(new Error('raw blob exceeds GitHub 100 MiB limit'));\n            return;\n          }\n          const merged = mergeCarry(carry, incoming);\n          const completeLength = merged.length - (merged.length % 3);\n          if (completeLength) {\n            controller.enqueue(ENCODER.encode(bytesToBase64(merged.subarray(0, completeLength))));\n          }\n          carry = merged.slice(completeLength);\n          if (controller.desiredSize != null && controller.desiredSize <= 0) return;\n        }\n      } catch (error) {\n        finished = true;\n        controller.error(error);\n      }\n    },\n    cancel(reason) {\n      finished = true;\n      return reader.cancel(reason).catch(() => {});\n    },\n  });\n}\n""", encoding='utf-8')

worker = ROOT / 'pages' / 'zz_cloud' / 'worker.js'
worker.write_text("""import { createGitHubBlobJsonStream } from './blob_stream.mjs';\n\nconst IMAGE_ROUTE = '/__gallery-image/';\nconst GITHUB_BLOB_ROUTE = '/__gallery-github-blob/';\nconst GITHUB_IMAGE_ROOT = 'https://raw.githubusercontent.com/Lidure/airi-gallery-images/main/';\nconst GITHUB_API_ROOT = 'https://api.github.com/repos/';\nconst GITHUB_MAX_BLOB_BYTES = 100 * 1024 * 1024;\nconst IMAGE_PATTERN = /^gallery\\/.+\\.(?:bmp|gif|jpe?g|jfif|png|tiff?|webp)$/i;\nconst REPO_COMPONENT = /^[A-Za-z0-9_.-]{1,100}$/;\n\nfunction getImagePath(url) {\n  if (!url.pathname.startsWith(IMAGE_ROUTE)) return null;\n  const encodedPath = url.pathname.slice(IMAGE_ROUTE.length);\n  if (!encodedPath || encodedPath.length > 700) return null;\n  let path;\n  try {\n    path = encodedPath.split('/').map(decodeURIComponent).join('/');\n  } catch {\n    return null;\n  }\n  if (!IMAGE_PATTERN.test(path)) return null;\n  const segments = path.split('/');\n  if (segments.some(segment => !segment || segment === '.' || segment === '..' || segment.includes('\\\\'))) {\n    return null;\n  }\n  return segments.map(encodeURIComponent).join('/');\n}\n\nfunction getGitHubBlobTarget(url) {\n  if (!url.pathname.startsWith(GITHUB_BLOB_ROUTE)) return null;\n  const suffix = url.pathname.slice(GITHUB_BLOB_ROUTE.length);\n  const parts = suffix.split('/');\n  if (parts.length !== 2) return null;\n  let owner;\n  let repo;\n  try {\n    owner = decodeURIComponent(parts[0]);\n    repo = decodeURIComponent(parts[1]);\n  } catch {\n    return null;\n  }\n  if (!REPO_COMPONENT.test(owner) || !REPO_COMPONENT.test(repo)) return null;\n  return { owner, repo };\n}\n\nfunction upstreamUrl(path, version) {\n  const url = new URL(GITHUB_IMAGE_ROOT + path);\n  if (version && /^[a-f\\d]{7,64}$/i.test(version)) url.searchParams.set('v', version);\n  return url;\n}\n\nasync function proxyImage(request, path) {\n  const requestUrl = new URL(request.url);\n  const upstream = upstreamUrl(path, requestUrl.searchParams.get('v'));\n  const response = await fetch(upstream, {\n    method: request.method,\n    headers: { Accept: 'image/*' },\n    cf: {\n      cacheEverything: true,\n      cacheTtl: 86400,\n      cacheTtlByStatus: {\n        '200-299': 86400,\n        '404': 60,\n        '400-499': 0,\n        '500-599': 0,\n      },\n    },\n  });\n  const headers = new Headers(response.headers);\n  if (response.ok) {\n    headers.set('Cache-Control', 'public, max-age=3600, s-maxage=86400, stale-while-revalidate=604800');\n  }\n  headers.set('X-Content-Type-Options', 'nosniff');\n  return new Response(response.body, { status: response.status, headers });\n}\n\nfunction jsonError(message, status) {\n  return new Response(JSON.stringify({ message }), {\n    status,\n    headers: {\n      'Content-Type': 'application/json; charset=utf-8',\n      'Cache-Control': 'no-store',\n      'X-Content-Type-Options': 'nosniff',\n    },\n  });\n}\n\nasync function proxyGitHubBlob(request, target) {\n  if (request.method !== 'POST') {\n    return new Response('Method Not Allowed', { status: 405, headers: { Allow: 'POST' } });\n  }\n  const requestUrl = new URL(request.url);\n  const origin = request.headers.get('Origin');\n  if (origin && origin !== requestUrl.origin) return jsonError('跨站上传请求已拒绝', 403);\n\n  const authorization = request.headers.get('Authorization') || '';\n  if (!/^(?:token|Bearer)\\s+\\S+$/i.test(authorization)) {\n    return jsonError('GitHub Token 缺失或格式无效', 401);\n  }\n  if (!request.body) return jsonError('上传内容为空', 400);\n\n  const declaredSize = Number(\n    request.headers.get('X-Gallery-Blob-Size') || request.headers.get('Content-Length') || 0,\n  );\n  if (!Number.isFinite(declaredSize) || declaredSize < 0) return jsonError('上传大小无效', 400);\n  if (declaredSize > GITHUB_MAX_BLOB_BYTES) return jsonError('图片超过 GitHub 单文件 100 MiB 限制', 413);\n\n  const apiUrl = `${GITHUB_API_ROOT}${encodeURIComponent(target.owner)}/${encodeURIComponent(target.repo)}/git/blobs`;\n  const body = createGitHubBlobJsonStream(request.body, { maxBytes: GITHUB_MAX_BLOB_BYTES });\n  let upstream;\n  try {\n    upstream = await fetch(apiUrl, {\n      method: 'POST',\n      headers: {\n        Accept: 'application/vnd.github+json',\n        Authorization: authorization,\n        'Content-Type': 'application/json',\n        'X-GitHub-Api-Version': '2022-11-28',\n      },\n      body,\n    });\n  } catch (error) {\n    const message = String(error?.message || error || '');\n    if (/exceeds/i.test(message)) return jsonError('图片超过 GitHub 单文件 100 MiB 限制', 413);\n    return jsonError('Cloudflare 到 GitHub 的大图片上传连接失败', 502);\n  }\n\n  const headers = new Headers({\n    'Content-Type': upstream.headers.get('Content-Type') || 'application/json; charset=utf-8',\n    'Cache-Control': 'no-store',\n    'X-Content-Type-Options': 'nosniff',\n  });\n  for (const name of ['retry-after', 'x-ratelimit-remaining', 'x-ratelimit-reset']) {\n    const value = upstream.headers.get(name);\n    if (value) headers.set(name, value);\n  }\n  return new Response(upstream.body, { status: upstream.status, headers });\n}\n\nexport default {\n  async fetch(request, env) {\n    const url = new URL(request.url);\n    const blobTarget = getGitHubBlobTarget(url);\n    if (blobTarget) return proxyGitHubBlob(request, blobTarget);\n\n    const path = getImagePath(url);\n    if (path) {\n      if (request.method !== 'GET' && request.method !== 'HEAD') {\n        return new Response('Method Not Allowed', { status: 405, headers: { Allow: 'GET, HEAD' } });\n      }\n      try {\n        return await proxyImage(request, path);\n      } catch {\n        return new Response('Image proxy unavailable', { status: 502 });\n      }\n    }\n\n    return env.ASSETS.fetch(request);\n  },\n};\n""", encoding='utf-8')

wrangler = ROOT / 'pages' / 'zz_cloud' / 'wrangler.jsonc'
wrangler.write_text("""{\n  \"$schema\": \"node_modules/wrangler/config-schema.json\",\n  \"name\": \"airi-gallery\",\n  \"main\": \"./worker.js\",\n  \"compatibility_date\": \"2026-06-29\",\n  \"observability\": {\n    \"enabled\": true\n  },\n  \"assets\": {\n    \"directory\": \".\",\n    \"binding\": \"ASSETS\",\n    \"run_worker_first\": [\"/__gallery-image/*\", \"/__gallery-github-blob/*\"]\n  },\n  \"compatibility_flags\": [\n    \"nodejs_compat\"\n  ]\n}\n""", encoding='utf-8')

readme = ROOT / 'README.md'
replace_once(
    readme,
    "大于 16 MiB 的批次改为逐个编码，降低浏览器内存峰值。",
    "GitHub 单图达到 4 MiB 时改走同源 Cloudflare Worker 原始二进制流式代理，浏览器不再构造整张 Base64 大 JSON；含大图的批次串行创建 blob，降低内存峰值并改善跨境上传稳定性。",
)

print('cloud large upload production patch applied')
